fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(9);
    let tap: bool = down == 1 && prev == 0;
    host::display::state_set(9, down);
    let phase: i32 = host::display::state_get(0);
    if phase == 0 {
        host::display::clear(0x101020);
        host::display::draw_string(8, 10, "TAP TO ARM", 0xffffff, 2);
        host::display::draw_string(8, 40, "LAST MS", 0x808080, 1);
        host::display::draw_number(70, 40, host::display::state_get(4), 0x00ff00, 1);
        if tap {
            let n: i32 = host::display::state_get(5) + 1;
            host::display::state_set(5, n);
            host::display::state_set(1, 30 + hash(n) % 120);
            host::display::state_set(2, 0);
            host::display::state_set(0, 1);
        }
    }
    if phase == 1 {
        host::display::clear(0x400000);
        host::display::draw_string(8, 10, "WAIT FOR GREEN", 0xff8080, 2);
        let mut wait: i32 = host::display::state_get(2) + 1;
        host::display::state_set(2, wait);
        if tap {
            host::display::state_set(0, 0);
        } else {
            if wait >= host::display::state_get(1) {
                host::display::state_set(3, 0);
                host::display::state_set(0, 2);
            }
        }
    }
    if phase == 2 {
        host::display::clear(0x004000);
        host::display::draw_string(8, 10, "TAP NOW", 0x80ff80, 3);
        let mut gone: i32 = host::display::state_get(3) + 1;
        host::display::state_set(3, gone);
        if tap {
            host::display::state_set(4, gone * 16);
            host::display::state_set(0, 0);
        }
    }
    host::display::present();
}
